export function withRequestStatus() {
  return signalStoreFeature(
    withState({ status: 'idle' as 'idle' | 'loading' | 'error', error: null as string | null }),
    withComputed(({ status }) => ({ isLoading: computed(() => status() === 'loading') })),
  );
}
export const OrdersStore = signalStore(
  withEntities<Order>(),
  withRequestStatus(),
  withMethods(store => ({ /* load, cancel, ... */ })),
);

withMethods((store, api = inject(ProductsApi)) => ({
  search: rxMethod<string>(pipe(
    debounceTime(300),
    distinctUntilChanged(),
    tap(() => patchState(store, { status: 'loading' })),
    switchMap(q => api.search(q).pipe(tapResponse({
      next: items => patchState(store, setAllEntities(items), { status: 'idle' }),
      error: () => patchState(store, { status: 'error' }),
    }))),
  )),
})),

@Injectable({ providedIn: 'root' })
export class FilterService {
  private readonly _filter = signal<Filter>(DEFAULT);
  readonly filter = this._filter.asReadonly();
  /** @deprecated użyj filter() */
  readonly filter$ = toObservable(this._filter);
  setFilter(f: Filter) { this._filter.set(f); }
}

effect(onCleanup => {
  const id = this.userId();
