  onCleanup(() => ctrl.abort());
  fetch(`/api/users/${id}`, { signal: ctrl.signal })
    .then(r => r.json())
    .then(u => this.user.set(u))
    .catch(e => { if (e.name !== 'AbortError') this.error.set(e); });
});
